-- Location match: University Union -> University Union (UU) (a8203f59-147d-424b-b8e2-21c1f802394f)
-- Match reason: exact alias match on 'university union'
WITH
resolved_location AS (
    SELECT 'a8203f59-147d-424b-b8e2-21c1f802394f'::uuid AS location_id
),
existing_event AS (
    SELECT event_id
    FROM events
    WHERE title = '1155 Live'
      AND start_date_time = TIMESTAMP '2026-03-24 11:55:00'
      AND end_date_time = TIMESTAMP '2026-03-24 14:00:00'
      AND location_id = (SELECT location_id FROM resolved_location)
    LIMIT 1
),
updated_existing_event AS (
    UPDATE events
    SET
        description = 'Kickstart your day with exciting live music, a lively atmosphere, and refreshing drinks.',
        event_type = 'CULTURAL'::event_type,
        status = 'SCHEDULED'::event_status,
        capacity = NULL,
        is_public = TRUE,
        updated_at = CURRENT_TIMESTAMP
    WHERE event_id IN (SELECT event_id FROM existing_event)
    RETURNING event_id
),
inserted_event AS (
    INSERT INTO events (
        title,
        description,
        location_id,
        start_date_time,
        end_date_time,
        event_type,
        capacity,
        registered_count,
        is_public,
        status
    )
    SELECT
        '1155 Live',
        'Kickstart your day with exciting live music, a lively atmosphere, and refreshing drinks.',
        (SELECT location_id FROM resolved_location),
        TIMESTAMP '2026-03-24 11:55:00',
        TIMESTAMP '2026-03-24 14:00:00',
        'CULTURAL'::event_type,
        NULL,
        0,
        TRUE,
        'SCHEDULED'::event_status
    WHERE NOT EXISTS (
        SELECT 1 FROM existing_event
    )
    RETURNING event_id
),
resolved_event AS (
    SELECT event_id FROM inserted_event
    UNION ALL
    SELECT event_id FROM updated_existing_event
    LIMIT 1
),
upserted_details AS (
    INSERT INTO event_details (
        event_id,
        source_url,
        source_location_name,
        source_location_url,
        room_detail,
        address,
        image_url,
        website_url,
        metadata
    )
    SELECT
        (SELECT event_id FROM resolved_event),
        'https://calendar.unt.edu/event/1155-live-5653',
        'University Union',
        'https://calendar.unt.edu/university_union',
        NULL,
        '1155 Union Circle, Denton, TX 76201',
        'https://localist-images.azureedge.net/photos/51994785198379/huge/b8d12f68b6f25cc425b5cb71ca9cce6d386a442b.jpg',
        'https://studentaffairs.unt.edu/university-union/university-program-council/index.html',
        '{"Alcohol Will Be Served": ["No"], "Audience": ["Undergraduate Students", "Graduate Students"], "Cost": ["Free"], "Department": ["Division of Student Affairs"], "Event Security Needed": ["No"], "Event Type": ["Social & Entertainment", "Student Life"], "Expected Attendance": ["100-500"], "Group": ["University Program Council", "University Union"], "Hashtag": ["#UNTUPC"], "Large Event Parking Needed": ["No"], "Minor Participants": ["No"], "Tags": ["live music"], "Topics": ["Giveaways & Free Stuff"], "Website": ["https://studentaffairs.unt.edu/univer..."]}'::jsonb
    WHERE EXISTS (SELECT 1 FROM resolved_event)
    ON CONFLICT (event_id) DO UPDATE
    SET
        source_url = EXCLUDED.source_url,
        source_location_name = EXCLUDED.source_location_name,
        source_location_url = EXCLUDED.source_location_url,
        room_detail = EXCLUDED.room_detail,
        address = EXCLUDED.address,
        image_url = EXCLUDED.image_url,
        website_url = EXCLUDED.website_url,
        metadata = EXCLUDED.metadata,
        updated_at = CURRENT_TIMESTAMP
    RETURNING event_detail_id
),
assigned_tags AS (
    INSERT INTO event_tag_assignments (event_id, event_tag_id)
    SELECT
        (SELECT event_id FROM resolved_event),
        t.event_tag_id
    FROM event_tags t
    WHERE t.name IN ('alcohol-served:No', 'attendance:100-500', 'audience:Graduate Students', 'audience:Undergraduate Students', 'cost:Free', 'group:University Program Council', 'group:University Union', 'live music', 'minor-participants:No', 'parking-needed:No', 'security-needed:No', 'source-location:University Union', 'source-type:Social & Entertainment', 'source-type:Student Life')
      AND EXISTS (SELECT 1 FROM resolved_event)
    ON CONFLICT DO NOTHING
    RETURNING event_tag_assignment_id
)
SELECT event_id FROM resolved_event;

