    SELECT '02d9bf16-eedc-4bb5-a194-d35c705501bb'::uuid AS location_id
),
existing_event AS (
    SELECT event_id
    FROM events
    WHERE title = 'Junior Recital: Samuel Yi, viola'
      AND start_date_time = TIMESTAMP '2026-03-24 18:30:00'
      AND end_date_time = TIMESTAMP '2026-03-25 00:00:00'
      AND location_id = (SELECT location_id FROM resolved_location)
    LIMIT 1
),
updated_existing_event AS (
    UPDATE events
    SET
        description = 'Important Links and Information Program Please note, this program is subject to change. Final program will be available by the day of the performance. Livestream is not available for this event. This event is free and open to the public with general seating.',
        event_type = 'WORKSHOP'::event_type,
        status = 'SCHEDULED'::event_status,
        capacity = NULL,
        is_public = TRUE,
        updated_at = CURRENT_TIMESTAMP
    WHERE event_id IN (SELECT event_id FROM existing_event)
    RETURNING event_id
),
inserted_event AS (
    INSERT INTO events (
        title,
        description,
        location_id,
        start_date_time,
        end_date_time,
        event_type,
        capacity,
        registered_count,
        is_public,
        status
    )
    SELECT
        'Junior Recital: Samuel Yi, viola',
        'Important Links and Information Program Please note, this program is subject to change. Final program will be available by the day of the performance. Livestream is not available for this event. This event is free and open to the public with general seating.',
        (SELECT location_id FROM resolved_location),
        TIMESTAMP '2026-03-24 18:30:00',
        TIMESTAMP '2026-03-25 00:00:00',
        'WORKSHOP'::event_type,
        NULL,
        0,
        TRUE,
        'SCHEDULED'::event_status
    WHERE NOT EXISTS (
        SELECT 1 FROM existing_event
    )
    RETURNING event_id
),
resolved_event AS (
    SELECT event_id FROM inserted_event
    UNION ALL
    SELECT event_id FROM updated_existing_event
    LIMIT 1
),
upserted_details AS (
    INSERT INTO event_details (
        event_id,
        source_url,
        source_location_name,
        source_location_url,
        room_detail,
        address,
        image_url,
        website_url,
        metadata
    )
    SELECT
        (SELECT event_id FROM resolved_event),
        'https://calendar.unt.edu/event/junior-recital-samuel-yi-viola1',
        'Paul Voertman Concert Hall at the Music Building',
        'https://calendar.unt.edu/voertman_hall_at_the_music_building',
        'Paul Voertman Concert Hall',
        '415 S. Avenue C, Denton, TX 76201',
        'https://localist-images.azureedge.net/photos/46924297381760/huge/bc83267bed0b1d303cb74437f873cbfa2bd2e558.jpg',
        'http://music.unt.edu',
        '{"Audience": ["Alumni", "Faculty", "Future Students", "General Public", "Parents & Families", "Staff", "Undergraduate Students", "Graduate Students"], "Department": ["College of Music"], "Event Type": ["Social & Entertainment"], "Expected Attendance": ["Less than 100"], "Group": ["UNT College of Music"], "Minor Participants": ["Yes"], "Tags": ["strings", "Student Recitals"], "Website": ["http://music.unt.edu"]}'::jsonb
    WHERE EXISTS (SELECT 1 FROM resolved_event)
    ON CONFLICT (event_id) DO UPDATE
    SET
        source_url = EXCLUDED.source_url,
        source_location_name = EXCLUDED.source_location_name,
        source_location_url = EXCLUDED.source_location_url,
        room_detail = EXCLUDED.room_detail,
        address = EXCLUDED.address,
        image_url = EXCLUDED.image_url,
        website_url = EXCLUDED.website_url,
        metadata = EXCLUDED.metadata,
        updated_at = CURRENT_TIMESTAMP
    RETURNING event_detail_id
),
assigned_tags AS (
    INSERT INTO event_tag_assignments (event_id, event_tag_id)
    SELECT
        (SELECT event_id FROM resolved_event),
        t.event_tag_id
    FROM event_tags t
    WHERE t.name IN ('attendance:Less than 100', 'audience:Alumni', 'audience:Faculty', 'audience:Future Students', 'audience:General Public', 'audience:Graduate Students', 'audience:Parents & Families', 'audience:Staff', 'audience:Undergraduate Students', 'group:UNT College of Music', 'minor-participants:Yes', 'room:Paul Voertman Concert Hall', 'source-location:Paul Voertman Concert Hall at the Music Building', 'source-type:Social & Entertainment', 'strings', 'Student Recitals')
      AND EXISTS (SELECT 1 FROM resolved_event)
    ON CONFLICT DO NOTHING
    RETURNING event_tag_assignment_id
)
SELECT event_id FROM resolved_event;

